export function InlineCurrencySwitcher({ ar }: { ar: boolean }) {
  const svc = CurrencyService.getInstance();
  const [cur, setCur] = useState<SupportedCurrency>(svc.current);
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  const popular: SupportedCurrency[] = ['JOD', 'USD', 'EUR', 'SAR', 'EGP', 'GBP'];

  useEffect(() => {
    const handleMouseDown = (event: MouseEvent) => {
      if (ref.current && !ref.current.contains(event.target as Node)) {setOpen(false);}
    };
    document.addEventListener('mousedown', handleMouseDown);
    return () => document.removeEventListener('mousedown', handleMouseDown);
  }, []);

  const select = (code: SupportedCurrency) => {
    svc.setCurrency(code);
    setCur(code);
    setOpen(false);
  };

  return (
    <div ref={ref} style={{ position: 'relative', display: 'inline-block' }}>
      <button
        type="button"
        onClick={() => { void setOpen(value => !value); }}
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: 6,
          height: 36,
          padding: '0 12px',
          borderRadius: R.full,
          background: open ? C.cyanDim : 'var(--secondary)',
          border: `1px solid ${open ? 'var(--border)' : 'var(--border)'}`,
          cursor: 'pointer',
          fontSize: TYPE.size.sm,
          fontWeight: TYPE.weight.bold,
          color: open ? 'var(--foreground)' : 'var(--foreground)',
          fontFamily: F,
        }}
      >
        <span style={{ fontSize: TYPE.size.xs, color: 'var(--muted-foreground)' }}>
          {ar ? 'العملة' : 'Currency'}
        </span>
        <span>{cur}</span>
        <ChevronDown size={12} color={'var(--primary)'} />
      </button>
      {open ? (
        <div
          style={{
            position: 'absolute',
            top: 'calc(100% + 8px)',
            insetInlineStart: 0,
            minWidth: 156,
            background: glass(0.96),
            border: `1px solid ${'var(--border)'}`,
            borderRadius: 14,
            boxShadow: SH.lg,
            zIndex: 100,
            overflow: 'hidden',
          }}
        >
          {popular.map(code => (
            <button
              type="button"
              key={code}
              onClick={() => { void select(code); }}
              style={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                width: '100%',
                padding: '9px 12px',
                border: 'none',
                background: cur === code ? 'var(--secondary)' : 'transparent',
                cursor: 'pointer',
                fontSize: TYPE.size.sm,
                fontWeight: cur === code ? TYPE.weight.bold : TYPE.weight.medium,
                color: cur === code ? 'var(--foreground)' : 'var(--foreground)',
                fontFamily: F,
              }}
            >
              <span>{code}</span>
              <span style={{ color: 'var(--muted-foreground)', fontSize: TYPE.size.xs }}>
                {svc.getSymbol(code)}
              </span>
            </button>
          ))}
        </div>
      ) : null}
    </div>
  );
}

export function SOSButton({ ar }: { ar: boolean }) {
  const [pressed, setPressed] = useState(false);
  const [confirm, setConfirm] = useState(false);

  const handleSOS = () => {
    if (!confirm) {
      setConfirm(true);
      return;
    }
    window.open('tel:911', '_self');
    setPressed(true);
    setTimeout(() => {
      setPressed(false);
      setConfirm(false);
    }, 4000);
  };

  return (
    <div style={{ position: 'relative', display: 'inline-flex', alignItems: 'center', gap: 10 }}>
      <motion.button
        onClick={() => { void handleSOS(); }}
        whileTap={{ scale: 0.97 }}
        style={{
          height: 42,
          padding: '0 16px',
          borderRadius: R.full,
          background: confirm ? 'var(--destructive)' : 'var(--secondary)',
          border: `1px solid ${confirm ? `${'var(--destructive)'}AA` : `${'var(--destructive)'}40`}`,
          cursor: 'pointer',
          display: 'flex',
          alignItems: 'center',
          gap: 8,
          fontSize: TYPE.size.sm,
          fontWeight: TYPE.weight.bold,
          color: confirm ? 'var(--foreground)' : 'var(--destructive)',
          fontFamily: F,
          boxShadow: confirm ? `0 0 0 4px ${'color-mix(in srgb, var(--destructive) 14%, transparent)'}` : 'none',
        }}
      >
        <Phone size={14} />
        {pressed
          ? ar
            ? 'جار الاتصال...'
            : 'Calling...'
          : confirm
            ? ar
              ? 'اضغط مرة أخرى للتأكيد'
              : 'Tap again to confirm'
            : 'SOS'}
      </motion.button>
      {confirm && !pressed ? (
        <button
          type="button"
          onClick={() => { void setConfirm(false); }}
          style={{
            background: 'none',
            border: 'none',
            cursor: 'pointer',
            color: 'var(--muted-foreground)',
            fontSize: TYPE.size.xs,
            fontFamily: F,
          }}
        >
          {ar ? 'إلغاء' : 'Cancel'}
        </button>
      ) : null}
    </div>
  );
}

export function TrustScoreCard({
  score,
  ar,
  user,
}: {
  /** `null` until the signed-in user's real score resolves — never a mock. */
  score: number | null;
  ar: boolean;
  user?: {
    emailVerified?: boolean;
    phoneVerified?: boolean;
    verified?: boolean;
    trips?: number;
    rating?: number;
  };
}) {
  const [expanded, setExpanded] = useState(false);
  const resolved = typeof score === 'number' && Number.isFinite(score);
  const pct = resolved ? Math.max(0, Math.min(100, score)) : 0;
  const emailPoints = user?.emailVerified ? 10 : 0;
  const phonePoints = user?.phoneVerified ? 10 : 0;
  const identityPoints = user?.verified ? 15 : 0;
  const tripsPoints = Math.min(user?.trips ?? 0, 50) * 0.4;
  const ratingPoints = Math.max(0, Math.min(5, user?.rating ?? 0)) * 2;
  const basePoints = 45;
  const factors = [
    { label: ar ? 'المعلومات الأساسية' : 'Base profile', weight: basePoints, yours: basePoints, color: 'var(--primary)' },
    { label: ar ? 'تأكيد البريد الإلكتروني' : 'Email confirmation', weight: 10, yours: emailPoints, color: 'var(--primary)' },
    { label: ar ? 'تأكيد رقم الهاتف' : 'Phone confirmation', weight: 10, yours: phonePoints, color: C.green },
    { label: ar ? 'التحقق من الهوية' : 'ID verification', weight: 15, yours: identityPoints, color: C.gold },
    { label: ar ? 'الرحلات المكتملة' : 'Completed trips', weight: 20, yours: Math.min(tripsPoints, 20), color: C.gold },
    { label: ar ? 'تقييمات المستخدمين' : 'User ratings', weight: 10, yours: Math.min(ratingPoints, 10), color: C.green },
  ];
  const color = pct >= 80 ? C.green : pct >= 60 ? C.gold : 'var(--destructive)';

  return (
    <div
      style={{
        borderRadius: 16,
        padding: '20px 22px',
        background: glass(0.88),
        border: `1px solid ${'var(--border)'}`,
        boxShadow: SH.sm,
      }}
    >
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 14,
          flexWrap: 'wrap',
        }}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: 14 }}>
          <div
            style={{
              width: 56,
              height: 56,
              borderRadius: '50%',
              background: `${color}18`,
              border: `1px solid ${color}38`,
              display: 'grid',
              placeItems: 'center',
              boxShadow: `0 0 0 6px ${color}10`,
            }}
          >
            {resolved ? (
              <span style={{ fontSize: '1.25rem', fontWeight: TYPE.weight.ultra, color, fontFamily: F }}>
                {score}
              </span>
            ) : (
              <Skeleton w={26} h={18} radius={6} />
            )}
          </div>
          <div style={{ display: 'grid', gap: 4 }}>
            <div
              style={{
                fontWeight: TYPE.weight.black,
                color: 'var(--foreground)',
                fontSize: TYPE.size.lg,
                fontFamily: F,
              }}
            >
              {ar ? 'مؤشر الثقة' : 'Trust score'}
            </div>
            <div style={{ fontSize: TYPE.size.sm, color: 'var(--muted-foreground)', fontFamily: F }}>
              {!resolved
                ? tx('homeSections.trustScoreLoading')
                : pct >= 80
                  ? ar
                    ? 'مؤشر قوي قبل الحجز أو العرض'
                    : 'Strong standing before booking or offering'
                  : pct >= 60
                    ? ar
                      ? 'مؤشر جيد ويستفيد من مزيد من النشاط'
                      : 'Healthy standing with room to improve'
                    : ar
                      ? 'يحتاج إلى تقوية قبل الاعتماد الكامل'
                      : 'Needs stronger standing before full trust'}
            </div>
          </div>
        </div>
        {resolved ? (
          <button
            type="button"
            onClick={() => { void setExpanded(value => !value); }}
            style={{
              height: 34,
              padding: '0 12px',
              borderRadius: R.full,
              background: 'var(--secondary)',
              border: `1px solid ${'var(--border)'}`,
              cursor: 'pointer',
              display: 'flex',
              alignItems: 'center',
              gap: 6,
              fontSize: TYPE.size.xs,
              color: 'var(--foreground)',
              fontWeight: TYPE.weight.semibold,
              fontFamily: F,
            }}
          >
            <Info size={12} color={'var(--primary)'} />
            {ar ? 'طريقة الحساب' : 'How it works'}
            {expanded ? (
              <ChevronUp size={12} color={'var(--muted-foreground)'} />
            ) : (
              <ChevronDown size={12} color={'var(--muted-foreground)'} />
            )}
          </button>
        ) : null}
      </div>
      <div
        style={{
          marginTop: 16,
          height: 7,
          borderRadius: 9999,
          background: 'var(--secondary)',
          overflow: 'hidden',
        }}
      >
        <div
          style={{
            height: '100%',
            width: `${pct}%`,
            borderRadius: 9999,
            background: `linear-gradient(90deg, ${color}, ${'var(--primary)'})`,
            transition: 'width 0.8s ease',
          }}
        />
      </div>
      <AnimatePresence>
        {expanded ? (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            transition={{ duration: 0.22 }}
            style={{ overflow: 'hidden' }}
          >
            <div style={{ marginTop: 18, paddingTop: 16, borderTop: `1px solid ${'var(--border)'}` }}>
              <p
                style={{
                  fontSize: TYPE.size.sm,
                  color: 'var(--muted-foreground)',
                  fontFamily: F,
                  margin: '0 0 14px',
                }}
              >
                {ar
                  ? 'يتكوّن المؤشر من عوامل واضحة تؤثر مباشرة على الثقة في الحجز والحركة.'
                  : 'The score is built from clear factors that directly affect booking confidence.'}
              </p>
              {factors.map(factor => (
                <div key={factor.label} style={{ marginBottom: 12 }}>
                  <div
                    style={{
                      display: 'flex',
                      justifyContent: 'space-between',
                      alignItems: 'center',
                      marginBottom: 5,
                      gap: 12,
                    }}
                  >
                    <span style={{ fontSize: TYPE.size.sm, color: 'var(--foreground)', fontFamily: F }}>
                      {factor.label}
                    </span>
                    <span
                      style={{
                        fontSize: TYPE.size.xs,
                        fontWeight: TYPE.weight.bold,
                        color: factor.color,
                        fontFamily: F,
                      }}
                    >
                      {factor.yours}/{factor.weight}
                    </span>
                  </div>
                  <div
                    style={{
                      height: 5,
                      borderRadius: 9999,
                      background: 'var(--secondary)',
                      overflow: 'hidden',
                    }}
                  >
                    <div
                      style={{
                        height: '100%',
                        width: `${(factor.yours / factor.weight) * 100}%`,
                        borderRadius: 9999,
                        background: factor.color,
                      }}
                    />
                  </div>
                </div>
              ))}
            </div>
          </motion.div>
        ) : null}
      </AnimatePresence>
    </div>
  );
}
